User.deleteInvitation = async function (invitedBy, email) {
	const invitedByUid = await User.getUidByUsername(invitedBy);
	if (!invitedByUid) {
		throw new Error('[[error:invalid-username]]');
	}
	const tokens = await db.getSetMembers(`invitation:invited:${email}`);
	const invitations = await Promise.all(tokens.map(t => db.getObject(`invitation:token:${t}`)));
	for (const token of tokens.filter((t, index) => invitations[index] &&
		String(invitations[index].uid) === String(invitedByUid))) {
