async function deleteToken(token) {
	const tokenKey = `invitation:token:${token}`;
	const invitation = await db.getObject(tokenKey);
	if (!invitation || !invitation.email || !invitation.uid) {
		await db.delete(tokenKey);
		return;
	}

	const { uid, email } = invitation;
	const referenceKey = `invitation:uid:${uid}:invited:${email}`;
	await Promise.all([
		db.delete(tokenKey),
		db.setRemove(`invitation:invited:${email}`, token),
	]);
	const remainingTokens = await db.getSetMembers(`invitation:invited:${email}`);
	const remainingInvitations = await Promise.all(remainingTokens.map(t => db.getObject(`invitation:token:${t}`)));
	const nextToken = remainingTokens.find((t, index) => remainingInvitations[index] &&
		String(remainingInvitations[index].uid) === String(uid));
	if (nextToken) {
		await db.set(referenceKey, nextToken);
		const expiresIn = await db.pttl(`invitation:token:${nextToken}`);
		if (expiresIn > 0) {
			await db.pexpire(referenceKey, expiresIn);
		}
	} else {
		await db.delete(referenceKey);
		await deleteFromReferenceList(uid, email);
	}
}

async function deleteFromReferenceList(uid, email) {
	await db.setRemove(`invitation:uid:${uid}`, email);
	const count = await db.setCount(`invitation:uid:${uid}`);
	if (count === 0) {
		await db.setRemove('invitation:uids', uid);
	}
}

