		const expireIn = expireDays * 86400000;
		const expiresAt = Date.now() + expireIn;
		const tokenKey = `invitation:token:${token}`;
		const referenceKey = `invitation:uid:${uid}:invited:${email}`;
		const invitedKey = `invitation:invited:${email}`;

		await db.setAdd(`invitation:uid:${uid}`, email);
		await db.setAdd('invitation:uids', uid);
		await db.setObject(tokenKey, {
			uid,
			email,
			groupsToJoin: JSON.stringify(groupsToJoin),
		});
		await db.set(referenceKey, token);
		await db.setAdd(invitedKey, token);
		const invitedSetTtl = await db.pttl(invitedKey);
		const invitedSetExpiresAt = invitedSetTtl > 0 ? Math.max(expiresAt, Date.now() + invitedSetTtl) : expiresAt;
		await Promise.all([
			db.pexpireAt(tokenKey, expiresAt),
			db.pexpireAt(referenceKey, expiresAt),
			db.pexpireAt(invitedKey, invitedSetExpiresAt),
		]);

		const username = await User.getUserField(uid, 'username');
		const title = meta.config.title || meta.config.browserTitle || 'NodeBB';
		const subject = await translator.translate(`[[email:invite, ${title}]]`, meta.config.defaultLang);

		return {
